async function boot(){const saved=read(META,{});media=(saved.media||[]).filter(i=>i&&i.id&&['image','video'].includes(i.kind));audio=(saved.audio||[]).filter(i=>i&&i.id&&i.kind==='audio');overlay=saved.overlay?.id?saved.overlay:null;try{const rows=await dbOp('readonly',s=>s.getAll());for(const row of rows)handles.set(row.id,row);}catch{}$('fileAccessNote').textContent=window.showDirectoryPicker?'Original-location links. Saved folder permissions may need Relink after reopening.':'iPhone: local originals are selected for each session. Relink them after reopening. The app saves no media copies; iOS may create temporary picker files.';render();storeSettings();if('serviceWorker'in navigator){try{const reg=await navigator.serviceWorker.register('sw.js',{updateViaCache:'none'});await navigator.serviceWorker.ready;const cache=await caches.open('plapinator-9000-20261010-v1');const cached=await cache.match('index.html');$('offlineStatus').textContent=cached?'Offline app ready · media stays local':'Offline app is preparing; keep this page open online.';reg.addEventListener('updatefound',()=>status('App update downloading. Reopen after your reel to apply it.'));if(!navigator.serviceWorker.controller)status('Offline app installed. Reopen once to activate it.');}catch{$('offlineStatus').textContent='Offline installation failed. Reload while online.';}}else $('offlineStatus').textContent='This browser does not support offline installation.';}
